import { type TooltipGroup, createTooltipGroup } from "@cssints/headless";
import type { JSX } from "@solidjs/web";
import * as css from "cssints" with { type: "cssints" };
import { createContext, merge, omit, onCleanup, useContext } from "solid-js";

import { Button } from "./button.tsx";
import { type PartProps, renderPart, type Renderable } from "./render.tsx";
import { t } from "./theme.ts" with { type: "cssints" };

export interface TooltipProps {
  /** No tooltip while `true`, and no `aria-describedby`. */
  readonly disabled?: boolean;
  readonly children?: JSX.Element;
}

export type TooltipTriggerPartProps = PartProps;

export interface TooltipTriggerProps extends Renderable<TooltipTriggerPartProps, void> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

export interface TooltipContentProps extends Renderable<PartProps, void> {
  readonly class?: string;
  readonly children?: JSX.Element;
}

const TooltipContext = createContext<{
  readonly group: TooltipGroup;
  /** Hide after the primitive's hide delay: the bubble sits below the trigger, and a pointer crossing the gap leaves it. */
  readonly hideLater: () => void;
  readonly cancelHide: () => void;
}>();

const anchorClass = css.cn(css.position("relative"), css.display("inline-flex"));

// An anchor, not a measured layer: the bubble is absolute in the box around the trigger, so it needs no rect, no
// scroll or resize listener, and no portal. The cost is the wrapper and an `overflow: hidden` ancestor clipping it.
// No `display` here on purpose: the primitive hides the bubble with the `hidden` attribute, and a display declaration
// in the class would override the UA's `[hidden] { display: none }`.
const contentClass = css.cn(
  css.position("absolute"),
  css.insetBlockStart("100%"),
  css.insetInlineStart("0"),
  css.marginBlockStart(t.space._1),
  css.zIndex("var(--z-popover)"),
  css.width("max-content"),
  css.maxWidth("min(20rem, 100%)"),
  css.padding(t.space._1, t.space._2),
  css.borderRadius(t.radius.sm),
  css.bg(t.color.text),
  css.color(t.color.page),
  css.fontSize(t.font.sizeSm),
  css.boxShadow(t.shadow.popover),
);

/**
 * APG tooltip, styled: `Tooltip.Trigger` is the element the pointer or the focus lands on, `Tooltip.Content` is the text
 * bubble it describes. `createTooltipGroup` owns the visible state and wires `aria-describedby` to the bubble's id; the
 * kit adds the anchor the bubble floats from, the bubble's look, and the hide delay that keeps it hoverable (WCAG
 * 1.4.13): the primitive's own pointer handler hides at once, which a pointer crossing the few pixels between the
 * trigger and the bubble would never survive.
 *
 * The bubble is always in the DOM and `hidden` while the tooltip is off, because `aria-describedby` names it.
 */
export const Tooltip = (props: TooltipProps): JSX.Element => {
  const group = createTooltipGroup({
    triggers: [{}],
    get disabled() {
      return props.disabled;
    },
    // both immediate: the show delay is not wired, the primitive exposes it (`showDelayMs`) for a denser page
    openOnFocus: true,
    openOnHover: true,
  });
  let timer: ReturnType<typeof setTimeout> | undefined;
  const cancelHide = (): void => {
    if (timer !== undefined) {
      clearTimeout(timer);
      timer = undefined;
    }
  };
  const hideLater = (): void => {
    cancelHide();
    timer = setTimeout(() => {
      timer = undefined;
      group.hideTimer();
    }, group.hideDelayMs());
  };
  onCleanup(cancelHide);
  return (
    <TooltipContext value={{ group, hideLater, cancelHide }}>
      <div data-part="tooltip-anchor" class={anchorClass}>
        {props.children}
      </div>
    </TooltipContext>
  );
};

/** The described element: a `Button` unless `render` says otherwise. It carries the `aria-describedby`. */
export const TooltipTrigger = (props: TooltipTriggerProps): JSX.Element => {
  const { group, hideLater, cancelHide } = useContext(TooltipContext);
  const rest = omit(props, "render", "class", "children");
  // no `data-part` of its own: the part renders a `Button`, which owns the attribute, as `Dialog.Trigger` does
  const merged = merge(rest, group.triggerProps(0), () => ({
    get class() {
      return css.cn(props.class);
    },
    // focus never waits: the tooltip went with the focus, so it goes with it
    onBlur: () => {
      cancelHide();
      group.blur();
      group.hideTimer();
    },
    onPointerLeave: () => {
      group.pointerLeave();
      hideLater();
    },
  }));
  return renderPart(props, merged, undefined, (part) => (
    <Button {...part}>{props.children}</Button>
  ));
};

/** The text bubble: `role="tooltip"`, hidden while the trigger is not described by it. */
export const TooltipContent = (props: TooltipContentProps): JSX.Element => {
  const { group, hideLater, cancelHide } = useContext(TooltipContext);
  const merged = merge(group.tooltipProps(0), () => ({
    "data-part": "tooltip",
    get class() {
      return css.cn(contentClass, props.class);
    },
    // hovering the bubble keeps it open (the primitive's own handler would hide it as the pointer arrives)
    onPointerEnter: () => {
      cancelHide();
      group.pointerEnterTip();
    },
    onPointerLeave: () => {
      group.pointerLeave();
      hideLater();
    },
  }));
  return renderPart(props, merged, undefined, (part) => <span {...part}>{props.children}</span>);
};

import type { JSX } from "@solidjs/web";
import { untrack } from "solid-js";

/**
 * What a part hands to `render`: the props the part owns (`id`, `aria-*`, `data-part`, `class`) and the state it is in, as
 * accessors — Solid does not re-render a component, so a snapshot would be dead on the second read.
 *
 * Base UI's `render` takes an element and clones it with the part's props; Solid cannot clone (JSX is already a node), so
 * the element form becomes the function form and a component is that function: `render={(props) => <a {...props} />}`,
 * `render={Button}`.
 */
export type Render<P extends object, S> = (props: P, state: S) => JSX.Element;

/**
 * What a part hands to `render`: element-generic attributes, because the element is the caller's (`<a>`, `<textarea>`, a
 * component). `ref` stays the caller's too — a part cannot type a ref for an element it has not chosen.
 */
export type PartProps = Omit<JSX.HTMLAttributes<HTMLElement>, "ref"> & {
  readonly class?: string;
};

/** A part that anything can render: `render` replaces its element and keeps the props the part owns. */
export interface Renderable<P extends object, S> {
  readonly render?: Render<P, S> | undefined;
}

/**
 * Renders a part: the caller's `render` when it gave one, the part's own element otherwise. `render` is structural, so it is
 * read once (untracked): a part that swapped it at run time would need a remount, not an update.
 *
 * @param {Renderable<P, S>} part the component's props, for the `render` it may carry
 * @param {P} props the part's props, already merged with the caller's own and with `class` and `data-part`
 * @param {S} state the part's state, as accessors
 * @param {(props: P) => JSX.Element} fallback the element the part is by default
 * @returns {JSX.Element} the part
 */
export const renderPart = <P extends object, S>(
  part: Renderable<PartProps, S>,
  props: P,
  state: S,
  fallback: (props: P) => JSX.Element,
): JSX.Element => {
  const render = untrack(() => part.render);
  // the part hands more than `PartProps` (its own element's attributes: `type` on a button, `value` on an input); a render
  // function is typed by what every part guarantees, and reads the rest as the DOM attributes they are
  return render === undefined ? fallback(props) : render(props as PartProps, state);
};

import { look } from "@cssints/mise-en-mode" with { type: "cssints" };
import { check, createGlobalTheme, createTokens, media } from "cssints" with { type: "cssints" };

import { darkTheme, forcedColorsTheme, lightTokens } from "./tokens.ts";

// The theme the starters are written against: one lightness scale, one hue and one chroma per
// colour family, and the semantic colours made of them. The data lives in tokens.ts, so the
// registry can compile it to a plain theme.css without the cssints plugin; this module is the
// same theme for the components and the demo page, with the contrast gate.
const t = createTokens(lightTokens);

// The dark mode is the lightness scale turned over, so every step and every colour made of it follows: the text is still
// gray-1200, it is just a light gray now. The page and the surface are the reference's own dark values, and the popover shadow
// deepens because a shadow on a dark page reads as a smudge.
createGlobalTheme(t, media("(prefers-color-scheme: dark)"), darkTheme);

// The same dark look as a scope a page can ask for: `<div data-mode="dark">` moves every token inside it, and a surface or a
// frame under it follows without a prop. It is a mise-en-mode look, so it is in the `app` layer: a host's `author` or `viewer`
// look over the same marker wins without a specificity trick, and `data-mode="dark/color"` moves the colours alone. The media
// query above stays a global theme: a look is a `data-mode` scope, and the system preference is not one.
look(t, "dark", "app", darkTheme);

// One preset, because the theme is neutral: the reference's indigo, as its two numbers. The others are in its theme.css.
createGlobalTheme(t, '[data-tint="indigo"]', {
  hue: { tint: "284.23" },
  chroma: { tint: "0.25049" },
});

// On a dense screen (200dpi and up) the targets grow: the spacing steps and the text with them, as in the reference.
createGlobalTheme(t, media("(min-resolution: 200dpi)"), {
  space: { base: "calc(0.25rem * 1.25)" },
  font: { sizeSm: "0.9375rem", size: "1.0625rem", sizeLg: "1.25rem" },
});

// Windows high contrast mode throws the theme away and paints the system's own colours; forced-colors makes that explicit,
// since a component that reads a token here gets the system colour rather than the tint.
createGlobalTheme(t, media("(forced-colors: active)"), forcedColorsTheme);

// The pairs a reader meets on every page: body text, the second level of text, and a link on a card. Both modes and every
// theme above are checked (the preset too, since it sets the tokens the link is made of), and a ratio under the floor fails
// the build. 7 for text and 4.5 for the rest are the WCAG 2.x AAA and AA floors.
check.contrast(t.color.text, t.color.page, { min: 7 }); // the tabs skin's selected label
check.contrast(t.color.muted, t.color.page, { min: 4.5 }); // its unselected label
check.contrast(t.color.link, t.color.surface, { min: 4.5 });
check.contrast(t.color.placeholder, t.color.page, { min: 4.5 });
check.contrast(t.color.onHighlight, t.color.highlight, { min: 4.5 });
// The active tab's underline is a graphic against the page: 3 is the WCAG 1.4.11 floor for non-text contrast. The dark
// mode is the closest (3.55:1 without the preset, 3.17:1 with indigo), so a lighter highlight would break it.
check.contrast(t.color.highlight, t.color.page, { min: 3 });
// The focus ring is a graphic, not text: 3 is the WCAG 1.4.11 floor for a non-text contrast.
check.contrast(t.color.focusRing, t.color.page, { min: 3 }); // the tabs skin's ring

export { t };

import { Tooltip, TooltipContent, TooltipTrigger } from "./tooltip.tsx";
import { render } from "@solidjs/web";

/** What a mounted demo hands the test: where it lives and a teardown. */
export interface MountedTooltip {
  readonly root: HTMLElement;
  readonly dispose: () => void;
}

/**
 * Mounts the styled tooltip, a trigger and the text bubble it describes. The group owns the visible state and
 * the `aria-describedby`; the kit adds the immediate open on hover and focus and the hide delay that keeps the
 * bubble hoverable (the primitive's own pointer handler hides at once).
 */
export const mountTooltip = (config: { readonly disabled?: boolean } = {}): MountedTooltip => {
  const root = document.createElement("div");
  document.body.append(root);
  const dispose = render(
    () => (
      <Tooltip disabled={config.disabled}>
        <TooltipTrigger>Delete</TooltipTrigger>
        <TooltipContent>Deletes the file</TooltipContent>
      </Tooltip>
    ),
    root,
  );
  return {
    root,
    dispose: () => {
      dispose();
      root.remove();
    },
  };
};

import { flush } from "solid-js";
import { afterEach, describe, expect, it } from "vite-plus/test";
import { userEvent } from "vite-plus/test/browser";

import { type MountedTooltip, mountTooltip } from "./tooltip.fixture";

// @cssints/headless walks `createTooltipGroup` against the APG tooltip spec in test/tooltip.browser.test.tsx, so that
// file is the primitive's oracle. This file is the skin's: it mounts the starter in a real Chromium and opens it the
// two ways a reader does (hover and focus), then reads the bubble and `aria-describedby` the primitive built. The
// scenarios the primitive's walk drives as `prop` steps (a delay, a controlled host, the timer events) cannot be
// replayed from the skin: `Tooltip` owns its group, renders one trigger, and wires the two gestures only. Those
// remain the primitive's test.

const live: MountedTooltip[] = [];

const mounted = (config?: Parameters<typeof mountTooltip>[0]): MountedTooltip => {
  const instance = mountTooltip(config);
  live.push(instance);
  return instance;
};

afterEach(() => {
  for (const instance of live.splice(0)) {
    instance.dispose();
  }
});

/** Solid 2 applies setters and the primitive's effects on later turns. */
const settle = (): Promise<void> => new Promise((resolve) => setTimeout(resolve, 20));

const frame = (): Promise<void> =>
  new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(() => resolve())));

const waitFor = async (done: () => boolean, limit = 2000): Promise<void> => {
  const start = performance.now();
  while (!done()) {
    if (performance.now() - start > limit) {
      throw new Error("waitFor timed out");
    }
    await frame();
  }
};

const required = <T extends Element>(parent: ParentNode, selector: string): T => {
  const element = parent.querySelector<T>(selector);
  if (element === null) {
    throw new Error(`tooltip: no ${selector}`);
  }
  return element;
};

/** The trigger is the kit's `Button`; the bubble is the only `role=tooltip` in the tree. */
const trigger = (root: ParentNode): HTMLElement => required(root, '[data-part="button"]');
const bubble = (root: ParentNode): HTMLElement => required(root, '[role="tooltip"]');
const style = (element: Element): CSSStyleDeclaration => getComputedStyle(element);
const describedBy = (root: ParentNode): string | null =>
  trigger(root).getAttribute("aria-describedby");

describe("Tooltip", () => {
  it("is a bubble that is in the DOM and hidden until the trigger is described by it", async () => {
    const { root } = mounted();
    await settle();

    const tip = bubble(root);
    expect(tip.id).not.toBe("");
    expect(tip.hidden).toBe(true);
    // no display in the bubble's class: the UA's `[hidden] { display: none }` is what hides it
    expect(style(tip).display).toBe("none");
    expect(trigger(root).getAttribute("aria-describedby")).toBeNull();
    expect(tip.textContent).toBe("Deletes the file");

    // it floats in the anchor beside the trigger
    const anchor = required(root, '[data-part="tooltip-anchor"]');
    expect(style(anchor).position).toBe("relative");
    expect(style(tip).position).toBe("absolute");
  });

  it("shows on hover, and the trigger names it while it is up", async () => {
    const { root } = mounted();
    await settle();

    await userEvent.hover(trigger(root));
    flush();
    await settle();

    const tip = bubble(root);
    expect(tip.hidden).toBe(false);
    expect(style(tip).display).not.toBe("none");
    expect(describedBy(root)).toBe(tip.id);
  });

  it("hides after the hide delay when the pointer leaves the trigger", async () => {
    const { root } = mounted();
    await settle();

    await userEvent.hover(trigger(root));
    flush();
    await settle();
    expect(bubble(root).hidden).toBe(false);

    await userEvent.unhover(trigger(root));
    flush();
    // the kit's grace, not the primitive's immediate hide: a pointer crossing the gap must survive it
    await waitFor(() => bubble(root).hidden);
    expect(describedBy(root)).toBeNull();
  });

  it("shows with the focus and hides with the blur, without waiting", async () => {
    const { root } = mounted();
    await settle();

    trigger(root).focus();
    flush();
    await settle();
    expect(bubble(root).hidden).toBe(false);
    expect(describedBy(root)).toBe(bubble(root).id);

    trigger(root).blur();
    flush();
    // focus never waits: the tooltip went with the focus, so it goes with it
    expect(bubble(root).hidden).toBe(true);
    expect(describedBy(root)).toBeNull();
  });

  it("stays open while the pointer is on the bubble itself", async () => {
    const { root } = mounted();
    await settle();

    await userEvent.hover(trigger(root));
    flush();
    await settle();
    const tip = bubble(root);
    expect(tip.hidden).toBe(false);

    // Leaving the trigger arms the hide; entering the bubble cancels it. The two pointer moves are dispatched
    // back to back on the elements, as a pointer crossing the gap does: a Playwright hover has to resolve a
    // locator first, which under load outlasts the 300 ms grace the kit lays on purpose.
    trigger(root).dispatchEvent(new PointerEvent("pointerleave"));
    tip.dispatchEvent(new PointerEvent("pointerenter"));
    flush();
    await new Promise((resolve) => setTimeout(resolve, 400));
    expect(tip.hidden).toBe(false);

    // leaving the bubble hides it again, after the same grace
    tip.dispatchEvent(new PointerEvent("pointerleave"));
    flush();
    await waitFor(() => tip.hidden);
  });

  it("never opens while disabled, and no trigger is described", async () => {
    const { root } = mounted({ disabled: true });
    await settle();

    expect(describedBy(root)).toBeNull();
    await userEvent.hover(trigger(root));
    trigger(root).focus();
    flush();
    await settle();
    expect(bubble(root).hidden).toBe(true);
    expect(describedBy(root)).toBeNull();
  });
});

import solid from "@solidjs/vite-plugin";
import cssints, { targets } from "cssints/vite";
import { defineConfig } from "vite-plus";
import { playwright } from "vite-plus/test/browser-playwright";

// The conformance test a starter arrives with runs in a real Chromium: the scenario walk needs a
// real DOM and Solid 2's reactivity, not a simulated one.
export default defineConfig({
  // `evaluation.inline`: a browser-mode runner inlines everything as ESM, so the plugin's own
  // evaluation server keeps the framework's packages inlined (Solid resolves its client build by
  // them) and the rest external (Node loads their CJS). Without it, a click's target resolves
  // against a second copy of Solid and the walk reads a state the page never changed.
  plugins: [
    cssints({ evaluation: { inline: ["solid-js", "@solidjs/web", "@solidjs/signals"] } }),
    solid(),
  ],
  css: { transformer: "lightningcss", lightningcss: { targets } },
  // The plugin adds `import derived from "cssints/derived"` to a client module after the dep
  // scanner has run; pre-bundling it here is what keeps that from reloading the page mid-test.
  optimizeDeps: { include: ["cssints/derived"] },
  test: {
    // a browser test has no app entry: the sheet of the modules the test imports arrives through
    // `virtual:cssints.css`, and vitest drops CSS imports unless it is told to process them
    css: true,
    // the sheet is loaded by the test's imports, not before them
    setupFiles: ["src/sheet.ts"],
    include: ["src/components/ui/**/*.browser.test.tsx"],
    browser: {
      enabled: true,
      provider: playwright(),
      headless: true,
      viewport: { width: 1280, height: 1024 },
      instances: [{ browser: "chromium" }],
      // The default waits 60 s for a worker's iframe to come up, which a busy machine (or a CI runner with a dozen other
      // jobs) misses: the run then fails as `the iframe did not become ready` with no test having run. Nothing about a
      // test gets longer; this is the browser starting.
      connectTimeout: 120_000,
      // the iframe ready timeout is read from the config's own env, not from the process that started the run
      env: { VITEST_BROWSER_IFRAME_TIMEOUT: "120000" },
    },
  },
});

// The engine's sheet for a browser test: its content is the CSS of the modules transformed so far, so it is loaded once the
// test file's imports are in (in `beforeAll`, not as a static import: vitest resolves the graph as it goes, and a sheet loaded
// first is just the `@layer` statement). A component's conformance test clicks its parts, so the sheet has to be there.
import { beforeAll } from "vite-plus/test";

beforeAll(async () => {
  await import("virtual:cssints.css");
});
